import assert from 'node:assert/strict';
import { test } from 'node:test';

const optionsForOrdinaryData = { skip: true };

test('checks option-shaped data', { skip: false }, () => {
  const payload = { skip: true };
  assert.equal(payload.skip, optionsForOrdinaryData.skip);
});

test('checks another payload', () => {
  const payload = { skip: true };
  assert.equal(payload.skip, true);
});
